function describeItem(item, page) {
  return (
    detailTexts[item] ||
    `Раскрывает тему “${item}” внутри раздела “${page.title}” и помогает понять, как эта часть влияет на личную ситуацию клиента.`
  );
}

function localizeDetailItem(item, page, lang) {
  const copy = detailItemCopy[item] || {};
  return {
    title: localize(copy.title, lang, item),
    text: localize(copy.text, lang, describeItem(item, page)),
  };
}

function localizeDetailPage(page, lang) {
  const copy = detailPageCopy[page.slug] || {};
  return {
    slug: page.slug,
    label: localize(copy.label, lang, page.label),
    title: localize(copy.title, lang, page.title),
    price: page.price,
    lead: localize(copy.lead, lang, page.lead),
    visualAlt: page.visual ? localize(copy.visualAlt, lang, page.visual.alt) : "",
    items: page.items.map((item) => localizeDetailItem(item, page, lang)),
  };
}

function buildPageContent(page) {
  return {
    ru: localizeDetailPage(page, "ru"),
    ro: localizeDetailPage(page, "ro"),
    en: localizeDetailPage(page, "en"),
  };
}

function renderDetailedItems(items) {
  return items
    .map(
      (item, index) => `<li>
            <span class="item-number">${String(index + 1).padStart(2, "0")}</span>
            <div>
              <h3>${escapeHtml(item.title)}</h3>
              <p>${escapeHtml(item.text)}</p>
            </div>
          </li>`
    )
    .join("\n          ");
}

function renderHeroVisual(page) {
  if (!page.visual) return "";

  return `<figure class="section-visual">
            <img src="${page.visual.src}" alt="${escapeHtml(page.visual.alt)}" data-field-alt="visualAlt">
          </figure>`;
}

